<?php
require_once __DIR__ . '/tienda_helpers.php';
$ctx=require_customer();$user=$ctx['usuario'];$clienteId=$ctx['cliente_id'];$pdo=db();
$id=(int)($_GET['id']??0);
if($id){$st=$pdo->prepare("SELECT o.id,o.folio,o.fecha,o.estado,o.total,o.subtotal,o.impuesto_porcentaje,o.impuesto_monto,o.descuento_monto,o.metodo_pago,o.pago_estado,o.correo_recibo_estado,d.etiqueta,d.calle,d.numero_exterior,d.numero_interior,d.colonia,d.municipio,d.estado AS estado_direccion,d.codigo_postal,d.pais FROM erp_ordenes o LEFT JOIN cliente_direcciones d ON d.id=o.direccion_id WHERE o.id=? AND o.cliente_id=? AND o.origen='tienda' AND o.usuario_cliente_id=? LIMIT 1");$st->execute([$id,$clienteId,$user['id']]);$order=$st->fetch();if(!$order)json_response(['error'=>'Pedido no encontrado.'],404);
 $st=$pdo->prepare('SELECT d.producto_id,d.cantidad,d.precio_unitario,d.subtotal,p.nombre,p.imagen FROM erp_orden_detalle d JOIN productos p ON p.id=d.producto_id WHERE d.orden_id=?');$st->execute([$id]);$order['productos']=$st->fetchAll();$st=$pdo->prepare('SELECT estado,descripcion,fecha FROM erp_orden_historial WHERE orden_id=? ORDER BY fecha,id');$st->execute([$id]);$order['historial']=$st->fetchAll();$st=$pdo->prepare('SELECT metodo_pago,estado,referencia,detalles_json,fecha FROM tienda_pagos WHERE orden_id=?');$st->execute([$id]);$order['pago']=$st->fetch()?:null;$wallet=store_wallet($pdo,$clienteId);$cfg=$pdo->query('SELECT saldo_minimo_alerta FROM tienda_configuracion WHERE id=1')->fetchColumn();$order['saldo_monedero']=(float)$wallet['saldo'];$order['saldo_minimo_alerta']=(float)($cfg?:100);$order['alerta_monedero']=$order['saldo_monedero']<=$order['saldo_minimo_alerta'];json_response(['ok'=>true,'pedido'=>$order]);}
$st=$pdo->prepare("SELECT o.id,o.folio,o.fecha,o.estado,o.total,o.metodo_pago,o.pago_estado FROM erp_ordenes o WHERE o.cliente_id=? AND o.origen='tienda' AND o.usuario_cliente_id=? ORDER BY o.fecha DESC,o.id DESC");$st->execute([$clienteId,$user['id']]);json_response(['ok'=>true,'pedidos'=>$st->fetchAll()]);
